INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT138-S3-Q2$batch08$, 138, 3, 2, $batch08$Most Strongly Supported$batch08$, $batch08$Forest fragmentation occurs when development severs a continuous area of forest, breaking it down into small patches. Some animals, such as white-footed mice, thrive in conditions of forest fragmentation, reaching their highest population densities in small forest patches. These mice are the main carrier of the bacteria that cause Lyme disease, a debilitating illness that is often transmitted from white-footed mice to humans by deer ticks.$batch08$, $batch08$Which one of the following is most strongly supported by the information above?$batch08$, $batch08$D$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=138 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT138-S3-Q2$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$White-footed mice are very rarely found in unfragmented forests.$batch08$, $batch08$Too Strong$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT138-S3-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$The population density for most species of small animals increases when a continuous area of forest becomes fragmented.$batch08$, $batch08$Too Strong$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT138-S3-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$Forest fragmentation reduces the number and variety of animal species that an area can support.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT138-S3-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$Efforts to stop the fragmentation of forests can have a beneficial effect on human health.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT138-S3-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$Deer ticks reach their highest population densities in small forest patches.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT138-S3-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT138-S3-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Development breaks forests into small patches. White-footed mice thrive there, reaching their highest densities in small patches. These mice are the main carrier of the Lyme bacteria, which deer ticks often pass to humans.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer by following the chain: fragmentation → more mice → more of the main Lyme carrier → more chances for Lyme to reach people. Run it backward: stop fragmentation and you remove a condition that boosts the carrier.$batch08$), (2, $batch08$Goal$batch08$, $batch08$Preventing fragmentation can help human health.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT138-S3-Q2$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Highest densities in small patches doesn't make the mice rare elsewhere.$batch08$), ($batch08$B$batch08$, $batch08$The passage says "some animals" thrive in fragments. It says nothing about most species.$batch08$), ($batch08$C$batch08$, $batch08$Nothing tells us about the number or variety of species.$batch08$), ($batch08$D$batch08$, $batch08$Fragmentation favors the main Lyme carrier, so efforts against fragmentation *can* help health. "Can" keeps it modest.$batch08$), ($batch08$E$batch08$, $batch08$The mice peak in small patches. We don't know where the ticks peak.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT138-S3-Q2$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
